// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // fuzz on from address and a single recipient in the _tos array and a value
    function testFuzz_property(address from, uint256 v, address dummy) public {
        // Keep domain admissible: _tos must be non-empty and callee must be a contract we control.
        vm.assume(from != address(0));
        vm.assume(dummy != address(0));

        // Deploy a recording helper that implements transferFrom(address,address,uint256)
        // and always returns true (i.e., succeeds). This ensures the external call succeeds
        // and the reference implementation will return true; the mutant may not.
        Recorder r = new Recorder();

        // Prepare a one-element array for _tos
        address[] memory tos = new address[](1);
        tos[0] = address(r);

        // Ensure the call is made from some EOA (use vm.prank to set msg.sender if needed).
        // Call c.transfer and observe its boolean return via try/catch pattern.
        bool ok;
        try c.transfer(from, address(r), tos, v) returns (bool ret) {
            ok = ret; // record returned value
        } catch {
            // Should not revert for this scenario since recorder returns true and inputs are admissible
            ok = false;
        }

        // GENERAL RULE ASSERTION:
        // For all admissible inputs (non-empty _tos and a callee that returns success),
        // the reference contract returns true. The mutant that removed 'return true' will
        // sometimes complete but not return true; thus this assert distinguishes them.
        assertTrue(ok);
    }
}

// Recorder: matches the selector bytes4(keccak256("transferFrom(address,address,uint256)"))
// i.e. function transferFrom(address from, address to, uint256 v) external returns (bool)
contract Recorder {
    // record last call data for potential inspection (not used directly in assertion)
    address public lastFrom;
    address public lastTo;
    uint256 public lastV;
    uint256 public calls;

    // The function that C calls via encodeWithSelector(..., from, _tos[i], v)
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        lastFrom = from;
        lastTo = to;
        lastV = v;
        calls += 1;
        return true; // simulate successful callee
    }
}
